        angle = math.radians(i * (180 / num_points) - 90)
        radius = outer_radius if i % 2 == 0 else inner_radius
        points.append((cx + radius * math.cos(angle), cy + radius * math.sin(angle)))
    arcade.draw_polygon_filled(points, color)

